<template><SuperAdminLayout><header><div><p>9. SYSTEM MONITORING</p><h1>System Monitoring</h1><small>Live health overview for the software platform.</small></div><button @click="load">↻ Refresh</button></header><p class="checked">Last checked: {{date(data.checked_at)}}</p><div class="services"><article v-for="service in data.services||[]" :key="service.name"><span :class="service.status.toLowerCase()"></span><h2>{{service.name}}</h2><strong>{{service.status}}</strong><p>{{service.detail}}</p></article></div><section class="card"><h2>Operational Signals</h2><div class="signals"><div><span>Paid invoices today</span><strong>{{data.activity?.paid_invoices_today||0}}</strong></div><div><span>Failed logins today</span><strong>{{data.activity?.failed_logins_today||0}}</strong></div><div><span>Active emergency shutdowns</span><strong>{{data.activity?.active_shutdowns||0}}</strong></div></div></section></SuperAdminLayout></template>
<script setup>import{onMounted,ref}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const data=ref({});const date=v=>v?new Date(v).toLocaleString():'—';const load=async()=>{data.value=(await client.get('/super-admin/system-monitoring')).data.data||{}};onMounted(load)</script>
<style scoped>header{display:flex;justify-content:space-between;align-items:start;margin-bottom:8px}header p{margin:0;color:#2877ce;font-size:.72rem;font-weight:700;letter-spacing:.1em}h1{margin:5px 0;font-size:2rem}small,.checked{color:#718096}.checked{font-size:.8rem}.services{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.services article,.card{position:relative;background:#fff;border:1px solid #e3e8f1;border-radius:9px;padding:18px}.services span{position:absolute;width:9px;height:9px;right:16px;border-radius:50%;background:#f59e0b}.services span.healthy{background:#22c55e}.services h2,.card h2{font-size:1rem;margin:0 0 8px}.services strong{color:#167044}.services p{color:#718096;font-size:.8rem}.signals{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.signals div{padding:15px;background:#f7faff;border-radius:6px}.signals span{display:block;color:#718096;font-size:.8rem}.signals strong{font-size:1.6rem}button{border:0;border-radius:6px;background:#156ad1;color:#fff;padding:10px 16px}@media(max-width:900px){.services{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.services,.signals{grid-template-columns:1fr}}</style>
